import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'admin' }) {
  
  // 1️⃣ Admin Menu Items
  const adminMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '🧑‍🎓' },
    { name: 'Manage Subjects', icon: '📚' }, 
    { name: 'Manage Timetable', icon: '🏫' },
    { name: 'Reports', icon: '📊' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 2️⃣ Teacher Menu Items
  const teacherMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Activities', icon: '🧩' },
    { name: 'Upload Materials', icon: '📂' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Student Progress', icon: '📈' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 3️⃣ Student Menu Items
  const studentMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Study Materials', icon: '📚' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Class Timetable', icon: '🗓️' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 🔄 Role එක අනුව Menu එක තේරීම
  let menuItems = adminMenuItems;
  if (role === 'teacher') menuItems = teacherMenuItems;
  if (role === 'student') menuItems = studentMenuItems;

  return (
    <div style={styles.sidebar}>
      
      {/* 🟢 Top Brand Info */}
      <div style={styles.logoHeader}>
        <div style={styles.iconBox}>✏️</div>
        <div>
          <h2 style={styles.brandTitle}>AuraPen</h2>
          <span style={styles.roleSubtext}>{role.toUpperCase()} PORTAL</span>
        </div>
      </div>

      {/* 🟢 Menu Items Area */}
      <div style={styles.menuList}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.name;
          return (
            <button
              key={item.name}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                ...styles.navButton,
                backgroundColor: isActive ? '#15803d' : 'transparent', // Exact Green Active Highlight
                color: 'white',
                fontWeight: isActive ? 'bold' : 'normal',
              }}
            >
              <span style={{ fontSize: '18px' }}>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          );
        })}
      </div>

      {/* 🔴 Screen එක ඇතුළෙම සෙට් වෙන Red Logout Button */}
      <div style={styles.logoutContainer}>
        <button onClick={onLogoutClick} style={styles.logoutBtn}>
          🚪 Logout
        </button>
      </div>

    </div>
  );
}

const styles = {
  sidebar: {
    width: '250px',
    minWidth: '250px',
    height: '100%',            // Parent container height එකට auto set වෙනවා
    maxHeight: '100vh',        // Screen එකෙන් එළියට යන එක නවත්වනවා
    backgroundColor: '#0a101d', // Exact Original Deep Dark Navy Blue
    color: '#ffffff',
    display: 'flex',
    flexDirection: 'column',
    padding: '15px 12px',
    boxSizing: 'border-box',
    overflow: 'hidden',        // Logout එක හැංගෙන එක නවත්වයි
  },
  logoHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    paddingBottom: '12px',
    marginBottom: '8px',
  },
  iconBox: {
    width: '38px',
    height: '38px',
    backgroundColor: '#15803d',
    borderRadius: '10px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '18px',
  },
  brandTitle: {
    margin: 0,
    fontSize: '20px',
    fontWeight: 'bold',
    color: '#ffffff',
  },
  roleSubtext: {
    fontSize: '10px',
    fontWeight: 'bold',
    color: '#22c55e',
    letterSpacing: '0.5px',
  },
  menuList: {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: '4px',
    overflowY: 'auto',         // Button ගොඩක් තිබුණොත් මෙතන විතරක් scroll වෙයි
    paddingRight: '4px',
  },
  navButton: {
    width: '100%',
    textAlign: 'left',
    padding: '10px 14px',
    border: 'none',
    borderRadius: '12px',      // Screenshot එකේ තිබුණු Exact rounded shape එක
    cursor: 'pointer',
    fontSize: '14px',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    transition: 'all 0.15s ease',
  },
  logoutContainer: {
    paddingTop: '10px',
    marginTop: 'auto',         // Logout එක හැමවෙලේම Screen එකේ යටින්ම තියෙයි
  },
  logoutBtn: {
    width: '100%',
    padding: '10px',
    backgroundColor: '#ef4444', // Red Logout Button
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontWeight: 'bold',
    fontSize: '14px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    boxShadow: '0 3px 8px rgba(239, 68, 68, 0.3)',
  }
};
